OUT=Path(__file__).resolve().parent;ROOT=OUT.parent
def read(name):
    with (OUT/name).open("r",encoding="utf-8-sig",newline="") as h:return list(csv.DictReader(h))
def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def main():
    validation=json.loads((OUT/"validation_results.json").read_text(encoding="utf-8"));production=json.loads((OUT/"production_results.json").read_text(encoding="utf-8"));orch=json.loads((OUT/"orchestration_results.json").read_text(encoding="utf-8"))
